/**
 * @brief 二分查找汉字 16x16 字模 (字表按 UTF-8 字节序升序)
 * @param Utf8 UTF-8 编码的汉字字符串 (需含 '\0' 结尾)
 * @return 32 字节字模指针; 未命中返回 NULL
 * @note   与字模数组同 TU, 可 sizeof 取完整上界, 免去手工字数宏
 */
const uint8_t *LCD_FontFind(const char *Utf8)
{
    int32_t lo = 0;
    int32_t hi = (int32_t)(sizeof(LCD_CF16x16) / sizeof(LCD_CF16x16[0])) - 2; /* 去掉末尾哨兵 */

    while (lo <= hi)
    {
        int32_t mid = (lo + hi) / 2;
        int32_t cmp = strcmp(LCD_CF16x16[mid].Index, Utf8);
        if (cmp < 0)        lo = mid + 1;
        else if (cmp > 0)   hi = mid - 1;
        else                return LCD_CF16x16[mid].Data;
    }
    return NULL;
}
